with o as (select customer_id,count(distinct order_id) total_orders,sum(case when order_status not in ('CANCELLED','CANCELED') then total_amount else 0 end) lifetime_order_value,max(order_date) last_order_date from {{ ref('fact_orders') }} group by customer_id), p as (select customer_id,sum(amount) lifetime_payments,max(transaction_timestamp) last_payment_date from {{ ref('fact_payments') }} group by customer_id) select c.customer_id,c.customer_name,c.email,c.country,c.state,c.city,c.customer_segment,coalesce(o.total_orders,0) total_orders,coalesce(o.lifetime_order_value,0) lifetime_order_value,coalesce(p.lifetime_payments,0) lifetime_payments,a.website_event_count,a.session_count,a.support_ticket_count,a.marketing_impressions,a.marketing_clicks,a.marketing_conversions,o.last_order_date,p.last_payment_date,case when coalesce(o.total_orders,0)>=10 or coalesce(o.lifetime_order_value,0)>=5000 then 'HIGH_VALUE' when coalesce(o.total_orders,0)>=3 or coalesce(o.lifetime_order_value,0)>=1000 then 'MEDIUM_VALUE' when coalesce(o.total_orders,0)>0 then 'LOW_VALUE' else 'PROSPECT' end customer_value_segment from {{ ref('dim_customer') }} c left join o on c.customer_id=o.customer_id left join p on c.customer_id=p.customer_id left join {{ ref('fact_customer_activity') }} a on c.customer_id=a.customer_id
